#!/usr/bin/env node
/**
 * Tests for the lite path (args.targeted) at every size and its edges: size L runs targeted block gates and one full gate
 * before the final readers, a `targeted` the loop cannot use says so in `gaps`, a fix round that changes nothing does not
 * rerun the full gate, the full-gate runner is told the long timeout, and loop.md documents every size.
 * Harness: tools/dev-loop.harness.mjs.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { run, ARGS, ARGS_M, review, finding, impl, gate, tasksOf, isReview } from './dev-loop.harness.mjs';

const VERIFY = 'node --test x';
const TEMPLATE = 'node --test {files}';
const LITE = { ...ARGS, verify: VERIFY, targeted: TEMPLATE, start: { head: 'abc1234', dirty: ['notes/todo.md'] } };
const green = (extra = {}) => impl({ gate: gate(), ...extra });
const fullGates = (calls) => calls.filter((c) => /^full gate/.test(c.opts.label ?? '') && c.opts.agentType !== 'implementer');
const LOOP_MD = join(dirname(fileURLToPath(import.meta.url)), '..', 'skills', 'deliver', 'references', 'loop.md');

test('given a 5-task plan at size L with targeted, when the loop runs, then every block gate has --targeted and one full gate runs before the final readers', async () => {
  // Given
  const args = { ...ARGS_M, size: 'L', verify: VERIFY, targeted: TEMPLATE, plan: { tasks: tasksOf(5) } };
  const reviews = Array.from({ length: 12 }, () => review([]));

  // When
  const { calls } = await run(args, reviews, [], { implementer: () => green() });

  // Then
  const blocks = calls.filter((c) => c.opts.agentType === 'implementer');
  assert.ok(blocks.length >= 2);   // five tasks are cut into blocks of at most three
  for (const block of blocks) assert.match(block.prompt, /gate\.mjs --root [^\n]* --targeted 'node --test \{files\}'/, block.opts.label);
  const fulls = fullGates(calls);
  assert.equal(fulls.length, 1);
  assert.doesNotMatch(fulls[0].prompt.split('\n').find((l) => /gate\.mjs --root [^\n]* --test /.test(l) && !/--wait/.test(l)), /--targeted/);
  assert.ok(calls.indexOf(fulls[0]) < calls.findIndex((c) => isReview(c.opts.label)));
});

test('given targeted with no {files} placeholder, when the loop runs, then no gate is targeted and a gaps line says why', async () => {
  // Given
  const args = { ...ARGS, verify: VERIFY, targeted: 'node --test' };

  // When
  const { out, calls } = await run(args, [review([])], [green()]);

  // Then
  assert.ok(out.gaps.some((g) => /targeted/.test(g) && /\{files\}/.test(g)), JSON.stringify(out.gaps));
  assert.equal(calls.filter((c) => /--targeted/.test(c.prompt)).length, 0);
  assert.equal(fullGates(calls).length, 0);
});

test('given targeted with no verify command, when the loop runs, then no gate is targeted and a gaps line says why', async () => {
  // Given
  const args = { ...ARGS, targeted: TEMPLATE };

  // When
  const { out, calls } = await run(args, [review([])], [impl()]);

  // Then
  assert.ok(out.gaps.some((g) => /targeted/.test(g) && /verify/.test(g)), JSON.stringify(out.gaps));
  assert.equal(calls.filter((c) => /--targeted/.test(c.prompt)).length, 0);
});

test('given a fix round that left the tree unchanged, when the loop runs, then the full gate is not rerun', async () => {
  // Given
  const reviews = [review([], [finding()]), review([{ id: 'F1', status: 'closed' }])];
  const unchanged = green({ files: [], snapshot: { tree: 't1', files: ['src/Orders/OrdersQuery.cs'], churn: 0 } });

  // When
  const { out, calls } = await run(LITE, reviews, [green(), unchanged]);

  // Then
  assert.equal(out.status, 'OK');
  assert.ok(calls.some((c) => c.opts.label === 'fix round 1 findings'));
  assert.equal(fullGates(calls).length, 1);
});

test('given a fix round that changed the tree, when the loop runs, then the full gate runs again after it', async () => {
  // Given
  const reviews = [review([], [finding()]), review([{ id: 'F1', status: 'closed' }])];
  const changed = green({ snapshot: { tree: 't2', files: ['src/Orders/OrdersQuery.cs'], churn: 3 } });

  // When
  const { out, calls } = await run(LITE, reviews, [green(), changed]);

  // Then
  assert.equal(out.status, 'OK');
  assert.equal(fullGates(calls).length, 2);
});

test('given a lite run, when the full-gate runner is called, then its prompt carries the long shell timeout', async () => {
  // Given / When
  const { calls } = await run(LITE, [review([])], [green()]);

  // Then
  assert.match(fullGates(calls)[0].prompt, /timeout: 600000/);
});

test('given loop.md, when its targeted row is read, then it applies at every size and no longer says S and M only', () => {
  // Given
  const row = readFileSync(LOOP_MD, 'utf8').split(/\r?\n/).find((l) => l.startsWith('| `targeted`'));

  // When / Then
  assert.match(row, /every size/);
  assert.doesNotMatch(row, /S and M/);
});
